import { useState, useRef, useEffect, useCallback } from "react";
import ChatMessage from "./components/ChatMessage";
import TypingIndicator from "./components/TypingIndicator";
import SuggestedQuestions from "./components/SuggestedQuestions";

const API_BASE = process.env.REACT_APP_API_URL || "";

const SUGGESTED_INITIAL = [
  "How can I reduce my carbon footprint at home?",
  "What are the best zero-waste swaps for the kitchen?",
  "How do I start composting?",
  "What is a capsule wardrobe and why is it eco-friendly?",
  "How can I save water in daily life?",
  "What are sustainable alternatives to single-use plastics?",
];

const WELCOME_MESSAGE = {
  role: "assistant",
  content:
    "🌿 **Welcome to the Eco Lifestyle Agent!**\n\nI'm here to help you live a more sustainable, eco-friendly life. Ask me about reducing waste, green home tips, sustainable food choices, ethical shopping, carbon footprint, and much more.\n\nWhat would you like to explore today?",
  sources: [],
};

export default function App() {
  const [messages, setMessages]           = useState([WELCOME_MESSAGE]);
  const [input, setInput]                 = useState("");
  const [isLoading, setIsLoading]         = useState(false);
  const [sessionId, setSessionId]         = useState(null);
  const [error, setError]                 = useState(null);
  const [showSuggested, setShowSuggested] = useState(true);

  const chatEndRef = useRef(null);
  const inputRef   = useRef(null);
  const abortRef   = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isLoading]);

  const sendMessage = useCallback(
    async (text) => {
      const trimmed = (text || input).trim();
      if (!trimmed || isLoading) return;

      setInput("");
      setError(null);
      setShowSuggested(false);
      setMessages((prev) => [...prev, { role: "user", content: trimmed, sources: [] }]);
      setIsLoading(true);

      try {
        const controller = new AbortController();
        abortRef.current = controller;

        const res = await fetch(`${API_BASE}/chat`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: trimmed, session_id: sessionId }),
          signal: controller.signal,
        });

        if (!res.ok) {
          const errData = await res.json().catch(() => ({}));
          throw new Error(errData.detail || `Server error: ${res.status}`);
        }

        const data = await res.json();
        if (data.session_id && !sessionId) setSessionId(data.session_id);
        setMessages((prev) => [
          ...prev,
          { role: "assistant", content: data.answer, sources: data.sources || [] },
        ]);
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(err.message || "Something went wrong. Please try again.");
          setMessages((prev) => prev.slice(0, -1));
        }
      } finally {
        setIsLoading(false);
        inputRef.current?.focus();
      }
    },
    [input, isLoading, sessionId]
  );

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const handleNewChat = () => {
    if (abortRef.current) abortRef.current.abort();
    setMessages([WELCOME_MESSAGE]);
    setSessionId(null);
    setInput("");
    setError(null);
    setShowSuggested(true);
    setIsLoading(false);
    inputRef.current?.focus();
  };

  const charCount = input.length;

  return (
    <div className="min-h-screen flex flex-col bg-sage-50">

      {/* ═══════════════════════════════ HEADER ═══════════════════════════════ */}
      <header className="sticky top-0 z-20 bg-white/95 backdrop-blur-sm header-border shadow-card">
        <div className="max-w-3xl mx-auto px-4 py-3 flex items-center justify-between">

          {/* Logo + title */}
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="w-10 h-10 rounded-2xl bg-leaf-gradient flex items-center justify-center shadow-bubble-user">
                <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                  <path strokeLinecap="round" strokeLinejoin="round"
                    d="M12 2C6 2 3 7 3 12c0 2.5 1 4.8 2.6 6.5L3 21l3-1.4A9.9 9.9 0 0012 21c5.5 0 9-4 9-9s-3.5-10-9-10z" />
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 12c0-4 3-7 6-8" />
                </svg>
              </div>
              {/* Online dot */}
              <span className="absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full bg-green-400 border-2 border-white" />
            </div>

            <div>
              <h1 className="text-base font-bold text-forest-900 leading-tight tracking-tight">
                Eco Lifestyle Agent
              </h1>
              <p className="text-xs text-forest-500 leading-tight font-medium">
                Powered by IBM watsonx.ai
              </p>
            </div>
          </div>

          {/* Right side — status badge + new chat */}
          <div className="flex items-center gap-2">
            <span className="hidden sm:inline-flex items-center gap-1.5 text-xs font-medium text-forest-600 bg-forest-50 border border-forest-200 rounded-full px-2.5 py-1">
              <span className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" />
              Online
            </span>
            <button
              onClick={handleNewChat}
              className="flex items-center gap-1.5 text-sm font-semibold text-forest-700 bg-forest-50 border border-forest-200 rounded-full px-3.5 py-1.5 hover:bg-forest-100 hover:border-forest-400 hover:shadow-glow-sm transition-all duration-150 active:scale-95"
            >
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" />
              </svg>
              New Chat
            </button>
          </div>
        </div>
      </header>

      {/* ═══════════════════════════════ CHAT AREA ════════════════════════════ */}
      <main className="flex-1 overflow-hidden flex flex-col max-w-3xl w-full mx-auto px-4">
        <div
          className="flex-1 overflow-y-auto chat-scroll py-6"
          id="chat-container"
        >
          {messages.map((msg, idx) => (
            <ChatMessage
              key={idx}
              role={msg.role}
              content={msg.content}
              sources={msg.sources}
            />
          ))}
          {isLoading && <TypingIndicator />}
          <div ref={chatEndRef} />
        </div>
      </main>

      {/* ═══════════════════════════════ BOTTOM PANEL ═════════════════════════ */}
      <div className="sticky bottom-0 bg-white/90 backdrop-blur-md border-t border-forest-100/60 shadow-panel">
        <div className="max-w-3xl mx-auto px-4 pt-3 pb-4 flex flex-col gap-3">

          {/* Suggested questions */}
          {showSuggested && (
            <SuggestedQuestions
              questions={SUGGESTED_INITIAL}
              onSelect={(q) => sendMessage(q)}
            />
          )}

          {/* Error banner */}
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 text-red-700 rounded-2xl px-4 py-2.5 text-sm animate-fade-in shadow-sm">
              <svg className="w-4 h-4 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round"
                  d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              <span className="flex-1">{error}</span>
              <button
                onClick={() => setError(null)}
                className="text-red-400 hover:text-red-600 transition-colors ml-1 p-0.5 rounded-full hover:bg-red-100"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          )}

          {/* ── Input box ── */}
          <div className="input-ring px-3.5 py-2.5">
            <div className="flex items-end gap-2">
              {/* Leaf accent */}
              <svg className="w-4 h-4 text-forest-400 flex-shrink-0 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                <path strokeLinecap="round" strokeLinejoin="round"
                  d="M12 2C6 2 3 7 3 12c0 2.5 1 4.8 2.6 6.5L3 21l3-1.4A9.9 9.9 0 0012 21c5.5 0 9-4 9-9s-3.5-10-9-10z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 12c0-4 3-7 6-8" />
              </svg>

              <textarea
                ref={inputRef}
                className="flex-1 resize-none bg-transparent text-base text-gray-800 placeholder-gray-400 outline-none leading-relaxed max-h-36 min-h-[1.75rem]"
                placeholder="Ask about sustainable living…"
                rows={1}
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  e.target.style.height = "auto";
                  e.target.style.height = `${Math.min(e.target.scrollHeight, 144)}px`;
                }}
                onKeyDown={handleKeyDown}
                disabled={isLoading}
              />

              {/* Character count — fades in when typing */}
              {charCount > 0 && (
                <span className="text-xs text-gray-300 self-end mb-1 animate-fade-in tabular-nums">
                  {charCount}
                </span>
              )}

              {/* Send button */}
              <button
                onClick={() => sendMessage()}
                disabled={isLoading || !input.trim()}
                className={`
                  flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center
                  transition-all duration-150
                  ${isLoading || !input.trim()
                    ? "bg-gray-100 text-gray-300 cursor-not-allowed"
                    : "bg-leaf-gradient text-white hover:shadow-bubble-user active:scale-95"}
                `}
              >
                {isLoading ? (
                  <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/>
                    <path className="opacity-75" fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/>
                  </svg>
                ) : (
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                    <path strokeLinecap="round" strokeLinejoin="round"
                      d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                )}
              </button>
            </div>

            {/* Hint row */}
            <p className="text-xs text-gray-400 mt-1.5 pl-6">
              Press <kbd className="bg-gray-100 border border-gray-200 rounded px-1 font-mono">Enter</kbd> to send,
              <kbd className="bg-gray-100 border border-gray-200 rounded px-1 font-mono ml-1">Shift+Enter</kbd> for new line
            </p>
          </div>

          {/* Footer caption */}
          <p className="text-center text-xs text-gray-400 font-medium tracking-wide">
            🌱 Answers grounded in your eco knowledge base &nbsp;·&nbsp; IBM watsonx.ai
          </p>
        </div>
      </div>
    </div>
  );
}
