/**
 * SuggestedQuestions — horizontally scrollable chip row.
 * Each chip has a small leaf icon and animates in on mount.
 */

const CHIP_ICONS = {
  default: (
    <svg className="w-3.5 h-3.5 flex-shrink-0 text-forest-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
      <path strokeLinecap="round" strokeLinejoin="round"
        d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  ),
};

export default function SuggestedQuestions({ questions, onSelect }) {
  if (!questions || questions.length === 0) return null;

  return (
    <div className="animate-fade-in">
      <p className="text-[10px] font-semibold uppercase tracking-widest text-forest-500 mb-2 px-0.5">
        Suggested questions
      </p>
      <div className="flex gap-2 overflow-x-auto pb-1 hide-scrollbar">
        {questions.map((q, i) => (
          <button
            key={i}
            className="suggested-chip"
            onClick={() => onSelect(q)}
            style={{ animationDelay: `${i * 40}ms` }}
          >
            {CHIP_ICONS.default}
            {q}
          </button>
        ))}
      </div>
    </div>
  );
}
