import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

/**
 * ChatMessage — renders a single user or assistant bubble with
 * entrance animation, gradient bubbles, and rich source pills.
 */
export default function ChatMessage({ role, content, sources = [] }) {
  const isUser = role === "user";

  return (
    <div className={`flex items-end gap-2.5 mb-4 msg-enter ${isUser ? "flex-row-reverse" : "flex-row"}`}>

      {/* ── Avatar ── */}
      <div className={`
        w-8 h-8 rounded-2xl flex items-center justify-center flex-shrink-0 mb-0.5
        ${isUser
          ? "bg-leaf-gradient shadow-bubble-user"
          : "bg-gradient-to-br from-forest-100 to-sage-200 shadow-sm border border-forest-200/60"}
      `}>
        {isUser ? (
          <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round"
              d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
          </svg>
        ) : (
          /* Leaf icon for assistant */
          <svg className="w-4 h-4 text-forest-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
            <path strokeLinecap="round" strokeLinejoin="round"
              d="M12 2C6 2 3 7 3 12c0 2.5 1 4.8 2.6 6.5L3 21l3-1.4A9.9 9.9 0 0012 21c5.5 0 9-4 9-9s-3.5-10-9-10z" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 12c0-4 3-7 6-8" />
          </svg>
        )}
      </div>

      {/* ── Bubble + sources ── */}
      <div className={`flex flex-col gap-2 ${isUser ? "items-end" : "items-start"} max-w-[78%]`}>

        {/* Bubble */}
        <div className={isUser ? "chat-bubble-user" : "chat-bubble-assistant"}>
          {isUser ? (
            <p className="text-base leading-relaxed">{content}</p>
          ) : (
            <div className="prose-chat">
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
            </div>
          )}
        </div>

        {/* Source pills */}
        {!isUser && sources.length > 0 && (
          <div className="flex flex-wrap gap-1.5 pl-1">
            <span className="text-xs font-medium text-gray-400 self-center mr-0.5 uppercase tracking-wide">
              Sources
            </span>
            {sources.map((src, i) => {
              const barWidth = Math.round(src.score * 40);
              return (
                <span
                  key={i}
                  className="source-pill"
                  title={`Relevance score: ${(src.score * 100).toFixed(0)}%`}
                >
                  {/* Document icon */}
                  <svg className="w-3 h-3 flex-shrink-0 text-bark-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round"
                      d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  <span className="truncate max-w-[140px]">{src.title}</span>
                  {/* Relevance bar */}
                  <span
                    className="score-bar opacity-70"
                    style={{ width: `${barWidth}px` }}
                  />
                </span>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
